import React, { PropsWithChildren } from 'react';

import { container } from './MultiMeterBarChartOverlay.sty.js';
import { useMeterBarLayoutSize } from '../../../shared/context/MeterBarLayoutSize.context.js';
import { getChartElementsSizes } from '../../../shared/functions/get-chart-elements-sizes.js';
import { useMultiMeterBarChartTooltipData } from '../../context/MultiMeterBarChartTooltipContext.js';
import { MultiMeterBarChartTooltip } from '../MultiMeterBarChartTooltip.js';

// TODO use shared component for overlays if possible
export const MultiMeterBarChartOverlay = ({ children }: PropsWithChildren) => {
  const { size } = useMeterBarLayoutSize();
  const { chartHeight } = getChartElementsSizes(size);
  const { tooltipConfig } = useMultiMeterBarChartTooltipData();
  const isTooltipEnabled = tooltipConfig.enabled;

  return (
    <div
      style={{ height: chartHeight }}
      className={container}
      data-testid="overlay-wrapper"
    >
      {children}
      {isTooltipEnabled && <MultiMeterBarChartTooltip />}
    </div>
  );
};

MultiMeterBarChartOverlay['displayName'] = 'MultiMeterBarChartOverlay';
